mapper.insert:
insert into academic_agent_session (
  session_id, user_id, title, task_type, last_message, create_time, update_time
) values (
  #{sessionId}, #{userId}, #{title}, #{taskType}, #{lastMessage}, #{createTime}, #{updateTime}
)
on duplicate key update session_id = values(session_id)

mapper.update:
update academic_agent_session
set title = #{title},
    task_type = #{taskType},
    last_message = #{lastMessage},
    update_time = #{updateTime}
where session_id = #{sessionId}
  and user_id = #{userId}

mapper.insert:
insert into academic_agent_message (
  message_id, session_id, user_id, role, content, image_url, create_time
) values (
  #{messageId}, #{sessionId}, #{userId}, #{role}, #{content}, #{imageUrl}, #{createTime}
)

mapper.select:
select message_id, session_id, user_id, role, content, image_url, create_time
from academic_agent_message
where user_id = #{userId}
  and session_id = #{sessionId}
order by create_time asc, id asc

select session_id, user_id, title, task_type, last_message, create_time, update_time
from academic_agent_session
where user_id = #{userId}
  and session_id = #{sessionId}
limit 1

select session_id, user_id, title, task_type, last_message, create_time, update_time
from academic_agent_session
where user_id = #{userId}
order by update_time desc
limit #{limit}

mapper.delete:
delete from academic_agent_session
where user_id = #{userId}
  and session_id = #{sessionId}

delete from academic_agent_message
where user_id = #{userId}
  and session_id = #{sessionId}

delete from academic_agent_file
